// Test support for the generated pages: an `invoke` router that answers from
// `registry.generated.json` — exactly what `list_pages` and
// `describe_fleet_settings` return on a fresh store (regenerated by
// `REGEN_PAGE_DOCS=1 cargo fleet-test -- page_docs_are_current`) — so
// every renderer test runs against the real pages and the real registry.
// Imported by tests only.
import registry from './registry.generated.json';
import type { Descriptor, PagesBundle } from './pages';

export const bundle = {
  pages: registry.pages,
  sources: registry.sources,
  resources: registry.resources,
  actions: registry.actions,
} as unknown as PagesBundle;
export const allDescriptors = registry.descriptors as unknown as Descriptor[];

export function descriptorOf(key: string): Descriptor {
  const d = allDescriptors.find((x) => x.key === key);
  if (!d) throw new Error(`no descriptor for ${key}`);
  return d;
}

/** What each data source answers in tests. */
