/**
 * An `invoke` implementation over a live settings map: reads answer from it,
 * `set_fleet_setting` writes it (refusing a read-only key and an out-of-range
 * number the way the backend does) and returns the whole map. Anything else
 * goes to `fallback`.
 */
export function registryRouter(
  initial: Record<string, string> = {},
  fallback: (cmd: string, args?: unknown) => unknown = () => null,
) {
  const values: Record<string, string> = Object.fromEntries(
    allDescriptors.map((d) => [d.key, d.value]),
  );
  Object.assign(values, initial);
  const impl = async (cmd: string, args?: unknown): Promise<unknown> => {
    switch (cmd) {
      case 'list_pages':
        return bundle;
      case 'describe_fleet_settings':
        return allDescriptors.map((d) => ({ ...d, value: values[d.key], modified: values[d.key] !== d.default }));
      case 'get_fleet_settings':
        return { ...values };
      case 'set_fleet_setting': {
        const { key, value } = args as { key: string; value: string };
        const d = allDescriptors.find((x) => x.key === key);
        if (!d) throw { code: 'E_INVALID', message: `unknown setting ${key}` };
        if (d.owned_by) throw { code: 'E_INVALID', message: `${key} is read-only here` };
        if (d.kind.type === 'int' && !(Number(value) >= d.kind.min && Number(value) <= d.kind.max)) {
          throw {
            code: 'E_INVALID',
            message: `${key} must be an integer between ${d.kind.min} and ${d.kind.max}`,
          };
        }
        values[key] = value;
        return { ...values };
      }
      case 'fetch_page_source': {
        const { id } = args as { id: string };
        if (!(id in SOURCE_DATA)) throw { code: 'E_INVALID', message: `unknown data source ${id}` };
        return SOURCE_DATA[id];
      }
      default:
        return fallback(cmd, args);
    }
  };
  return { impl, values };
}

/** Open one of a record editor's tabs (the org's Overview, Members,
 *  Devices, Spend, Settings) once it is drawn. */
export async function openRecordTab(name: string): Promise<void> {
  const { waitFor, fireEvent } = await import('@testing-library/svelte');
  const tab = await waitFor(() => {
    const el = document.querySelector<HTMLElement>(`[data-testid="record-tabs"] [data-tab="${name}"]`);
    if (!el) throw new Error(`no ${name} tab`);
    return el;
  });
  await fireEvent.click(tab);
}
